insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 4, 1, $json${"week":4,"day":1,"title":"Not finished","heading":"Not finished","question":"how did he vanish from a room you were all standing in, and what did he mean?","steps":[{"t":"say","text":"*We're not finished with you.*\n\nThen the dark. Now one lamp is lit again, in a shaking hand, and the place where he knelt is empty.\n\nHis ropes lie on the stone. One set of footprints leads away through the ash. Nobody saw a thing. Nobody heard a blade."},{"t":"notice","lines":{"Might":{"first":"The ropes were cut with one stroke each.","second":"A sharp blade and a steady hand, in the pitch dark."},"Agility":{"first":"Nobody brushed against you.","second":"In a room this size, with all of you in it."},"Intellect":{"first":"Every lamp went at once, yours among them.","second":"That takes more than one pair of hands."},"Charm":{"first":"Wren has not let go of the sleeve she found in the dark.","second":"She did not cry out. She has learned not to."},"Craft":{"first":"The ropes lie where he knelt, still in their knots.","second":"Nobody untied anything. Nobody wasted a moment."},"Aim":{"first":"The ash is smooth right across the floor, but for your own prints and one line of his.","second":"For the moment."}}},{"t":"choice","id":0,"labels":["READ THE ASH","TAKE WREN UP FIRST"],"mode":"pick","branches":[{"options":[0],"text":"{F2} takes Wren up toward the air. Everyone else stands exactly where they are."},{"options":[1],"text":"You take her up to where the air is cooler, and come back down. {F1} has kept every boot off the ash for you."}]},{"t":"say","text":"She walks, with her hand in somebody's sleeve.","cond":{"on":"claim","key":"G3:united-effort-lost","has":false}},{"t":"say","text":"She is carried, with her cuts bound in strips of somebody's shirt.","cond":{"on":"claim","key":"G3:united-effort-lost","has":true}},{"t":"challenge","title":"THE ASH","desc":"One careless step, and it says nothing.","options":[{"attr":"Aim","verb":"pick his prints out from your own, by one lamp"},{"attr":"Intellect","verb":"work it outward from the ropes: where he knelt, where he must have turned"}],"reward":"+500g","fail":"your own prints are over his, and only the direction is left"},{"t":"say","text":"Heel, then toe. Evenly spaced. He did not run.\n\nHe walked out of this room, at the pace of a man leaving a church, through a passage none of you had noticed.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"Too many of your own boots have been across it. All the ash will give you is which way he went: a passage none of you had noticed.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"The ropes were cut clean.\n\nSomebody stood within arm's reach of you in the dark, with a blade, and used it on rope."},{"t":"say","text":"Garrick is still at your shoulder. *\"Every time they've had knives out at you,\"* he says, *\"not one of you has died.\"*"},{"t":"press","title":"FOLLOW THEM","detail":"down the passage, as far as the prints go","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"They end where the ash gives out and the rock turns to bare black glass. Beyond it the passage splits three ways into the dark.\n\nNo prints come in. Whoever cut him loose came over the glass, and was waiting there before the lamps went out.","cond":{"on":"press"}},{"t":"say","text":"You bring Wren up out of the Kiln into a grey dawn. Straight back across the ridges it is one long day's walk; the trail she left you wandered far more."},{"t":"say","text":"Where the burned country gives out, at the last black rock before the grass begins, there is a crack at head height that only someone looking back would see."},{"t":"act","label":"REACH IN"},{"t":"say","text":"The rock is warm from the ground beneath it. What is in the crack is cold.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Her mother is standing in the road outside Ashcombe, as if she has stood there every hour since you left. She does not run. She walks, very fast, and then she is on her knees in the ash with her daughter held so tight that neither of them can speak.\n\nBefore you go, Wren digs in her pocket. It rattles. She presses one chip of black glass into your palm, and does not let go of your hand until you have closed it."},{"t":"say","text":"Three children home. One left.\n\nThe ledger's last name, in that same small, careful hand: *Joss — Reedham.* On Meira's list, in her plain writing: *Lives with his grandmother. Carves little boats.* And under that, a line of her shorthand.\n\n*\"Reedham's a fishing village on the Stillwater, two days north,\"* Garrick says. *\"The old village is under the lake. She's marked the tower that still stands out of the water.\"*"},{"t":"say","text":"*Already with us.* Joss is not waiting to be taken.\n\n**A blade within arm's reach, in the dark, and it cut rope. Why are you still alive? The north road, at first light.**","pull":true},{"t":"summary","lines":["**NOT FINISHED** · Day 1","You earned: `[gold]` · Aim or Intellect `[growth]`","You learned: nobody fought to free him. **His ropes were cut, and he walked out.** Someone stood among you in the dark with a blade and touched nobody. Wren is home.","*On a failure:* You missed something in the ash. Someone at the fire may have seen it.","You hold: a chip of black glass, from Wren","Fragment: 1 found, locked","Tomorrow: **the north road, two days to the Stillwater**"]}]}$json$::jsonb, $json${"dc":8,"wDef":24,"wAtk":17,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 4, 2, $json${"week":4,"day":2,"title":"The north road","heading":"The north road","question":"who rode north ahead of you, and what are they carrying?","steps":[{"t":"say","text":"The north road runs long and empty through cold, open country: heather, wind, and now and then a shepherd's hut with its smoke going sideways.\n\nAt a ford, three men step out of the alders. They have counted your packs, and they have counted you wrong."},{"t":"fight","name":"THE MEN AT THE FORD","desc":"Not grey coats. Not good boots. Only hungry.","firstLines":null,"strikeFirst":{"on":"player"}},{"t":"say","text":"Between you, it is over quickly. These men do not vanish. They sit down in the shallows with their heads in their hands, and, being asked nothing, tell you everything.\n\nThey let yesterday's lot go by. Four riders, armed, with a little closed cart between them. Nobody's easy purse."},{"t":"say","text":"The one you put down first looks up at you out of the water and says he is sorry. He seems to mean it.","cond":{"on":"fight","won":true}},{"t":"say","text":"Low in the stone of the old ford, where the water runs over it, sits a carved housing."},{"t":"act","label":"CLOSE YOUR HAND ON IT"},{"t":"say","text":"It opens as your fingers shut. What is inside is colder than the river.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Beyond the ford the road forks. {F1} and {F3} walk the left. You take the right."},{"t":"act","label":"READ THE GROUND"},{"t":"say","text":"The lake road, the one to Reedham, has nothing on it but sheep.\n\nThe other has four horses and two thin wheels, a day old, going fast."},{"t":"notice","lines":{"Might":{"first":"The ruts are shallow, even in the soft ground by the water.","second":"Whatever is in that cart weighs almost nothing."},"Agility":{"first":"The horses were watered standing, and ridden on.","second":"Nobody got down."},"Intellect":{"first":"Joss is on the lake road. These are not.","second":"They are not going where the boy is."},"Charm":{"first":"Three hungry men let four riders pass, and tried you.","second":"You look like less trouble than you are."},"Craft":{"first":"One of the cart's wheels is new, and the other is not.","second":"They have come a long way fast, and mended as they went."},"Aim":{"first":"Two rode before the cart and two behind, all the way.","second":"Nobody rides like that around nothing."}}},{"t":"say","text":"At the fork a carter is watering his horses, and he is glad of anyone to talk to."},{"t":"challenge","title":"THE CARTER","desc":"He saw them. He will get round to it.","options":[{"attr":"Charm","verb":"let him run, and steer him"},{"attr":"Intellect","verb":"ask the one question that matters"}],"reward":"+500g","fail":"a long hour, and the best of the light"},{"t":"say","text":"He gets to the point.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"It takes a long hour of his opinions on the weather, the road and his brother-in-law. But he gets there.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"*\"Nothing heavy in that cart,\"* he says. *\"One box, no bigger than a bread crock. And they guarded it like it was the last gold in the world. Four armed men for one little box.\"*\n\nHe shakes his head. *\"No child, if that's what you're asking. I'd have heard a child.\"*"},{"t":"say","text":"He digs in his coat, and holds something out on his palm. *\"Paid for the water with this. Nobody'll take it off me.\"*\n\nA coin, old and heavy. On one side the king's face has been scraped away to bare metal. The other side, somebody has kept polished."},{"t":"act","label":"TAKE THE COIN"},{"t":"say","text":"A small box.\n\nYou have seen one. Two nights ago, under the Kiln, held against a man's chest as he went up the vent."},{"t":"say","text":"That night you camp in the lee of a dry-stone wall. Garrick passes his flask round. *\"It's terrible. Drink it anyway.\"*\n\nThen he pours one more cup than there are people, and sets it down at the empty place by the fire."},{"t":"say","text":"**Four armed men for one small box, riding away from the boy. What is in it? Reedham, by noon tomorrow.**","pull":true},{"t":"summary","lines":["**THE NORTH ROAD** · Day 2","You earned: `[gold]` · Charm or Intellect `[growth]`","You learned: the riders ahead of you carry **no child. One small box**, under four swords, and at the fork they turned away from the lake.","You hold: a coin with the king's face scraped off one side, and polished on the other","Fragments: 2 found","Tomorrow: **Reedham, on the Stillwater**"]}]}$json$::jsonb, $json${"dc":8,"wDef":24,"wAtk":17,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 4, 3, $json${"week":4,"day":3,"title":"Reedham","heading":"Reedham","question":"what happened to Joss?","steps":[{"t":"say","text":"Reedham sits on the shore of the Stillwater, a long grey lake so calm that it holds the sky like a mirror. Boats are drawn up on the shingle. Nets hang drying.\n\nAnd out on the water, a stone's throw from the shallows, a bell tower rises straight up out of the lake: roof gone, bell gone, its windows full of sky.\n\n*\"That's the old village,\"* a fisherman says, when he sees you staring. *\"Old Reedham. The valley flooded in my great-grandfather's time and we moved uphill. Dry year like this, you can walk some of its streets at the shallow end. Nobody does.\"*"},{"t":"say","text":"Joss's grandmother keeps the house at the top of the lane. She lets you in, and says one thing.\n\n*\"They asked for him by name,\"* she says, *\"and they knew the night he was born.\"*\n\nYou have heard those words before: at the mill, and in Ashcombe.\n\nAfter that she only stands, with her hand on the doorpost."},{"t":"say","text":"Notches, cut with a kitchen knife, fresh and pale in the old wood. One for every night.\n\nEight."},{"t":"say","text":"Eight nights. He was taken before you had even found Wren.\n\nThey needed Wren *only the once*, and kept her two weeks. They have kept Joss eight nights already.\n\nThey are waiting for something."},{"t":"choice","id":0,"labels":["THE SHELF","THE WINDOW"],"mode":"each","branches":[{"options":[0],"text":"A row of little boats, each no longer than a finger, each better than the one before. The newest has its hull and no mast. The knife is lying beside it."},{"options":[1],"text":"A lamp is burning in it, at noon.\n\nOn the shingle, later, the fisherman tells you why. In Reedham a lamp is lit in every window on a dark-moon night; it always has been. Joss came into the world with the whole village lit up round him. She has not let that one go out since he went."}]},{"t":"notice","lines":{"Might":{"first":"Her skiff has been hauled up above the storm line.","second":"She did that alone."},"Agility":{"first":"She crosses the room without once passing in front of the window.","second":"She will not put herself between that lamp and the lake."},"Intellect":{"first":"A lamp at noon is oil wasted, in a house with none to waste.","second":"It is not for her to see by."},"Charm":{"first":"There are two stools at the table, and she has sat on neither.","second":"She has not sat down since you came in."},"Craft":{"first":"The skiff has a sprung plank, stuffed with rag.","second":"It will float. It will not stay dry."},"Aim":{"first":"From her door you can see down the lane, over the shingle, to the tower in the water.","second":"And from the tower, this window."}}},{"t":"say","text":"She takes you down to the shingle herself, and puts the skiff's rope into your hand."},{"t":"challenge","title":"HER SKIFF","desc":"It leaks, and the wind is getting up off the lake.","options":[{"attr":"Craft","verb":"patch her first, and row her dry"},{"attr":"Might","verb":"row her hard, and beat the leak there"}],"reward":"+500g","fail":"you get there soaked, and bailing"},{"t":"say","text":"You reach the tower in good order.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You arrive soaked and bailing. But you arrive.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"Halfway out, Garrick is bailing with a tin cup. He does not look up. *\"I didn't leave a warm bar to drown in a lake. I'd like that noted.\"*"},{"t":"say","text":"The tower stands on stones far older than the rest of it. Worn into that rock, just above the waterline, is a shape you know: the mark from the Widow's Tooth, the mill, the Blackglass.\n\nBeside it is a housing, slick with lake-weed."},{"t":"act","label":"LAY YOUR PALM ON IT"},{"t":"say","text":"The lid lifts as if it had been waiting. What is inside is as cold as the water it has sat above for centuries.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Back on the shingle, beside the place her skiff was lying, there are keel-marks that are not hers. Fresh ones.\n\n**Someone has been rowing out to the drowned village by night. Old Reedham, at the shallow end, tomorrow.**","pull":true},{"t":"summary","lines":["**REEDHAM** · Day 3","You earned: `[gold]` · Craft or Might `[growth]`","You learned: Joss has been gone **eight nights**, cut one by one into his grandmother's doorpost. They held Wren two weeks for something they needed *only the once*. **They are waiting for something.**","You hold: her skiff","Fragments: 3 found","Tomorrow: **Old Reedham, the streets in the shallows**"]}]}$json$::jsonb, $json${"dc":8,"wDef":24,"wAtk":17,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 4, 4, $json${"week":4,"day":4,"title":"Old Reedham","heading":"The drowned streets","question":"who has been out in the drowned streets?","steps":[{"t":"say","text":"At the shallow end the Stillwater has drawn back far enough to leave Old Reedham's upper streets standing in the open: cobbles slick with weed, doorways full of silt, walls water-marked green to the height of your chest.\n\nFurther out, the same streets slope down, and simply go on under the water."},{"t":"notice","lines":{"Might":{"first":"The water-mark on every wall is level with your chest.","second":"All of this was under the lake, and will be again."},"Agility":{"first":"The weed is green on every cobble but those down the middle of one lane.","second":"It has been walked on."},"Intellect":{"first":"Nobody in Reedham walks these streets.","second":"Then nobody in Reedham would see who does."},"Charm":{"first":"One doorpost has notches cut up it, generations old: a child's height, year by year.","second":"Somebody counted on a doorpost here, too."},"Craft":{"first":"The market cross still stands square in its silt.","second":"Its lowest course is older stone than the rest, and better cut."},"Aim":{"first":"Out past the last roofs the reed island lies low on the water.","second":"It is the only thing on this lake a boat could hide behind."}}},{"t":"say","text":"In the mud of the lowest lane there are footprints, a few days old. Grown men's boots.\n\nAnd between them, smaller ones."},{"t":"challenge","title":"THE LOWEST LANE","desc":"Weed on wet stone, and the light going.","options":[{"attr":"Agility","verb":"follow them across the cobbles without going in"},{"attr":"Aim","verb":"pick them out by lamplight, stone by stone, and call the line"}],"reward":"+500g","fail":"you go into the water, and the lamp goes with you"},{"t":"say","text":"You follow them to the edge of the deep water, where they stop.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You lose them twice. Then a drowned cobble turns under your foot, and you are in to the waist, with the lamp gone out in your fist. {F2} finds the last of them by feel: at the edge of the deep water, where they stop.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"He was walked through here alive. And then they got into a boat."},{"t":"press","title":"THE SMALL PRINTS","detail":"read only his, back along the lane","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"In one place the small prints stop, and turn, with both heels dug in.\n\nStand where he stood. From here, and from nowhere else in the lane, you can see one window on the shore with a lamp in it.","cond":{"on":"press"}},{"t":"say","text":"In the old market cross, at the centre of the drowned square, is a carved housing, half buried."},{"t":"act","label":"SCRAPE THE SILT AWAY"},{"t":"say","text":"The stone lid slides back under your fingers.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"That evening you have Meira's notes open on your knee, and you find the page.\n\nShe had this line already. Every word of it, copied years ago from some other record, in her plain hand. And beside it, a note:\n\n*\"'Moon-blood' — the old songs' word for the marked.\"*"},{"t":"say","text":"The marked. Tamsin. Corin. Wren. Joss.\n\nYou.\n\nYou have known since the hill under the mill that you are marked. You had not known there was an old word for it, or that the Seekers left a warning with that word in it."},{"t":"say","text":"**A warning against what? The reed island, a mile out: the only place on this lake a boat can put in unseen.**","pull":true},{"t":"summary","lines":["**OLD REEDHAM** · Day 4","You earned: `[gold]` · Agility or Aim `[growth]`","You learned: **Joss was walked through the drowned streets alive**, a few days ago, and taken on by boat. And the old songs have a word for the marked, for him and for you: **moon-blood.** Today's fragment is a warning about it.","Fragments: 4 found","Tomorrow: **the reed island**"]}]}$json$::jsonb, $json${"dc":8,"wDef":24,"wAtk":17,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 4, 5, $json${"week":4,"day":5,"title":"The reed island","heading":"The reed island","question":"where did the boat take him, and what has it been doing since?","steps":[{"t":"say","text":"Fog comes down on the Stillwater in the morning, thick and white. You row into it, and the shore is gone behind you in a dozen strokes."},{"t":"challenge","title":"THE FOG","desc":"A mile of white water, and one grey shadow in it.","options":[{"attr":"Aim","verb":"hold your line on the tower, for as long as you can see it"},{"attr":"Craft","verb":"rig a trailing line off the stern, and keep her true by it"}],"reward":"+500g · **and you strike first**","fail":"you row in a circle, and **he strikes first**"},{"t":"say","text":"You come in behind the island, where the reeds are thickest, and nothing on it has heard you.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You row in a slow circle for an hour. When the reeds loom up out of the white, you are on the open side, and somebody on the island has been listening to your oars for some time.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"The island is a low hummock of willow and rushes. On its far side, drawn up where nobody on shore could see it, is a boat.\n\nPainted on its prow, small and neat, is a black circle.\n\nAnd there is a man sitting on its gunwale."},{"t":"fight","name":"THE MAN WITH THE BOAT","desc":"He was left to mind it.","firstLines":["You strike first.","He strikes first."],"strikeFirst":{"on":"challenge"}},{"t":"say","text":"He does not go for the boat. He goes into the reeds, and then into the water, and the fog closes over the place.\n\nThe boat is yours. Her skiff goes on a line behind it."},{"t":"say","text":"One of his oars is still in your hands. He let go of it sooner than be taken.","cond":{"on":"fight","won":true}},{"t":"act","label":"SEARCH IT"},{"t":"say","text":"Two pairs of oar-places, worn bright. A lamp bracket. Stern boards still wet.\n\nIn the bottom, among the rope, lie pale curls of whittled wood, still fresh. And a tiny hull, half shaped, split down the middle, and thrown away.\n\nSomebody small has been sitting here, carving."},{"t":"notice","lines":{"Might":{"first":"Two pairs of oars, for a boat this size.","second":"It is rowed hard, by four, and often."},"Agility":{"first":"He went into the reeds without a splash.","second":"He knows this island with his eyes shut."},"Intellect":{"first":"The stern boards are wet, and it has not rained.","second":"This boat was out on the lake last night."},"Charm":{"first":"The little hull was not dropped. It was thrown.","second":"He was angry with it. He is still himself."},"Craft":{"first":"The lamp bracket is set low, under the gunwale.","second":"A light carried there cannot be seen from the shore."},"Aim":{"first":"The black circle is no bigger than a coin.","second":"You would have to be this close to know whose boat it was."}}},{"t":"say","text":"It is a ferry. Somebody has been rowing between this island and the drowned village, night after night."},{"t":"say","text":"Among the willow roots is a stone older than the island's soil, and in it a housing the roots have half swallowed."},{"t":"act","label":"WORK YOUR FINGERS IN"},{"t":"say","text":"The moment they touch the lid, it opens.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"The fog lifts toward evening. The island has one rise, no higher than a man, and from the top of it there is one clear line across the water.\n\nThe drowned tower.\n\nAnd on the black lake between, moving away from you, low on the water: a lamp."},{"t":"say","text":"**Why would anyone keep watch on an empty tower? After that lamp, tonight, in their own boat.**","pull":true},{"t":"summary","lines":["**THE REED ISLAND** · Day 5","You earned: `[gold]` · Aim or Craft `[growth]`","You learned: the Order runs **a ferry** between the island and the drowned village, by night. **Joss is alive, and still carving.** And something on this lake is watching the tower.","You hold: **the Order's boat**","Fragments: 5 found","Tomorrow: **the tower, at night**"]}]}$json$::jsonb, $json${"dc":8,"wDef":24,"wAtk":17,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 4, 6, $json${"week":4,"day":6,"title":"The tower at night","heading":"The tower at night","question":"where is he held?","steps":[{"t":"say","text":"The lamp is out long before you reach the tower. There is nobody in it.\n\nThe last fragment is on the stair, not hidden at all: wedged in the angle of a step where the water once reached, as if it had waited out the flood."},{"t":"act","label":"TAKE IT"},{"t":"say","text":"**A locked Seeker Fragment has been added to your Chest.**\n\nThat is six.","fragment":true},{"t":"notice","lines":{"Might":{"first":"The boat you took sits lower than her skiff, and steadier.","second":"It was built to carry more than its rowers."},"Agility":{"first":"The stair is wet to the fourth step, and dry above.","second":"Somebody stood here tonight, and went no higher."},"Intellect":{"first":"A lamp came to this tower and went out, and no boat passed you going back.","second":"Then it has not gone back."},"Charm":{"first":"Nobody has said the boy's name since the island.","second":"Somebody has his little split hull in a pocket."},"Craft":{"first":"The bell-chamber's windows have no shutters left.","second":"A flame up there will not live long."},"Aim":{"first":"From up here you can see every light in Reedham.","second":"One window is brighter than all the rest."}}},{"t":"say","text":"Nobody suggests waiting for morning.\n\nYou lay the six out on the bell-chamber floor, by one lamp. The wind comes through the empty windows in gusts. Below, the lake slaps at the stones."},{"t":"act","label":"LAY THEM OUT"},{"t":"say","text":"They settle, as they have three times before. A map, old and exact. But there is light enough for one pair of eyes, and only while the flame lives.\n\n{F1} bends to read. The flame is yours to keep."},{"t":"challenge","title":"THE FLAME","desc":"One lamp, four empty windows, and the wind.","options":[{"attr":"Craft","verb":"build it a shelter from what you carry"},{"attr":"Aim","verb":"one spark, struck true and set where the gusts cannot reach it"}],"reward":"+500g","fail":"it goes out halfway, and the way has to be called again"},{"t":"say","text":"The flame holds. {F1} calls the way out as it comes, and then once more, slower, so that everyone has it.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"It goes out halfway through. It is lit again, and the way is called again from the start, slower, and louder, over the wind.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"Under Old Reedham. Down the stair of the drowned church, to a room below the streets where the lake stands knee-deep."},{"t":"say","text":"Then a gust takes the lamp.\n\nAnd in the dark, close, so close that it must have been lying in the black water right under the tower: wood knocks on wood.\n\nThen oars. Not careful now. Pulling hard, away from you, toward the drowned village."},{"t":"say","text":"Somebody was beneath you, and heard every word."},{"t":"say","text":"**Down the stair, into the boat you took from them, and after that sound. Now.**","pull":true},{"t":"summary","lines":["**THE TOWER AT NIGHT** · Day 6","You earned: `[gold]` · Craft or Aim `[growth]`","You learned: Joss is held in **a flooded room under Old Reedham, down the stair of the drowned church.** And for the first time you have heard them: **someone lay under the tower and listened** while the way was read out.","You hold: the map · the Order's boat","Fragments: 6 of 6 · the map is whole","Tomorrow: **THE GATHERING** · after the oars, across the black lake, together"]}]}$json$::jsonb, $json${"dc":8,"wDef":24,"wAtk":17,"fightReward":0}$json$::jsonb)
